<?php
/** Member 2, Feature 3 - Inspection audit detail. */
require_once __DIR__ . '/../../includes/auth.php'; require_role(['admin','production_manager','qc_officer']);
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id){flash_set('error','Invalid inspection ID.');redirect('modules/fabric_inspections/index.php');}
$stmt=$conn->prepare("SELECT fi.*,fl.lot_number,fl.fabric_type,fl.color,fl.received_quantity,fl.unit,fl.inspection_status,s.supplier_name,u.full_name inspector_name,u.username inspector_username FROM fabric_inspections fi JOIN fabric_lots fl ON fl.fabric_lot_id=fi.fabric_lot_id JOIN suppliers s ON s.supplier_id=fl.supplier_id JOIN users u ON u.user_id=fi.inspector_id WHERE fi.fabric_inspection_id=? LIMIT 1");
if(!$stmt){error_log($conn->error);flash_set('error','Inspection could not be loaded.');redirect('modules/fabric_inspections/index.php');}$stmt->bind_param('i',$id);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$r){flash_set('error','Inspection not found.');redirect('modules/fabric_inspections/index.php');}
$pageTitle='Fabric Inspection '.$r['lot_number'];$currentNav='fabric_inspections'; include __DIR__.'/../../includes/header.php';include __DIR__.'/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Fabric Inspection Record</h1><div class="page-subtitle">Audit #<?=(int)$r['fabric_inspection_id']?> &bull; Lot <?=e($r['lot_number'])?></div></div><div class="page-actions"><a class="btn btn-secondary" href="<?=e(url('modules/fabric_inspections/index.php'))?>">Back to Inspections</a><a class="btn btn-primary" href="<?=e(url('modules/fabric_receiving/view.php?id='.(int)$r['fabric_lot_id']))?>">View Fabric Lot</a></div></div>
<div class="card card-medium"><div class="card-header"><h2><?=e($r['lot_number'])?></h2><span class="badge <?=$r['result']==='Passed'?'badge-success':($r['result']==='Failed'?'badge-danger':'badge-warning')?>"><?=e($r['result'])?></span></div><div class="card-body"><table class="details-table"><tr><th>Supplier</th><td><?=e($r['supplier_name'])?></td></tr><tr><th>Fabric</th><td><?=e($r['fabric_type'])?><?= $r['color']?' — '.e($r['color']):''?></td></tr><tr><th>Received Quantity</th><td><?=number_format((float)$r['received_quantity'],2)?> <?=e($r['unit'])?></td></tr><tr><th>Inspected Quantity</th><td><?=number_format((float)$r['inspected_quantity'],2)?> <?=e($r['unit'])?></td></tr><tr><th>4-Point Penalty</th><td><?=(int)$r['penalty_points']?></td></tr><tr><th>Inspection Date</th><td><?=e(date('F d, Y',strtotime($r['inspection_date'])))?></td></tr><tr><th>Inspector</th><td><?=e($r['inspector_name']?:$r['inspector_username'])?></td></tr><tr><th>Result / Current Lot Status</th><td><?=e($r['result'])?> / <?=e($r['inspection_status'])?></td></tr><tr><th>Remarks</th><td><?=nl2br(e($r['remarks']?:'—'))?></td></tr></table></div></div>
<?php if(in_array($r['inspection_status'],['Passed','Conditionally Approved'],true)):?><div class="mt-4"><a class="btn btn-primary" href="<?=e(url('modules/fabric_allocations/create.php?lot_id='.(int)$r['fabric_lot_id']))?>">Allocate Approved Fabric</a></div><?php endif?>
